<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';
if($action==='save'){$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$url=trim((string)($_POST['youtube_url']??''));$desc=trim((string)($_POST['description']??''));$order=(int)($_POST['sort_order']??0);$parts=parse_url($url);$host=strtolower($parts['host']??'');$vid='';
if(in_array($host,['youtu.be','www.youtu.be'],true))$vid=trim($parts['path']??'','/');elseif(in_array($host,['youtube.com','www.youtube.com','m.youtube.com'],true)){$q=[];if(!empty($parts['query']))parse_str($parts['query'],$q);$vid=$q['v']??'';if(!$vid&&preg_match('~^/(embed|shorts)/([^/]+)~',$parts['path']??'',$m))$vid=$m[2];}
if($title===''||!preg_match('/^[A-Za-z0-9_-]{11}$/',$vid))throw new RuntimeException('Başlıq və düzgün YouTube linki daxil edin.');
if($id){$q=$pdo->prepare('UPDATE videos SET title=?,description=?,youtube_url=?,youtube_video_id=?,sort_order=?,is_published=? WHERE id=?');$q->execute([$title,$desc,$url,$vid,$order,isset($_POST['is_published'])?1:0,$id]);}else{$q=$pdo->prepare('INSERT INTO videos(title,description,youtube_url,youtube_video_id,sort_order,is_published) VALUES(?,?,?,?,?,?)');$q->execute([$title,$desc,$url,$vid,$order,isset($_POST['is_published'])?1:0]);}$success='Video yadda saxlanıldı.';
}elseif($action==='delete'){$q=$pdo->prepare('DELETE FROM videos WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Video silindi.';}
}catch(Throwable $x){$error=$x instanceof PDOException?'Məlumat bazası xətası.':$x->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM videos WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT * FROM videos ORDER BY sort_order,id DESC')->fetchAll();admin_header('Videolar','videos');?>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif;?>
<div class="content-grid"><section class="panel"><h2><?= $edit?'Videonu redaktə et':'YouTube video əlavə et' ?></h2><form class="admin-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><label>Video başlığı<input name="title" required maxlength="220" value="<?=e($edit['title']??'')?>"></label><label>YouTube linki<input type="url" name="youtube_url" required value="<?=e($edit['youtube_url']??'')?>" placeholder="https://youtu.be/..."></label><label>Təsvir<textarea name="description" rows="5"><?=e($edit['description']??'')?></textarea></label><label>Sıralama<input type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label><label class="check-label"><input type="checkbox" name="is_published" <?=(!$edit||!empty($edit['is_published']))?'checked':''?>> Saytda göstər</label><div class="form-actions"><button class="btn-admin">Yadda saxla</button><?php if($edit):?><a class="btn-secondary" href="videos.php">Ləğv et</a><?php endif;?></div></form></section>
<section class="panel"><h2>Video siyahısı</h2><div class="table-wrap"><table><thead><tr><th>Video</th><th>Status</th><th>Əməliyyat</th></tr></thead><tbody><?php foreach($rows as $v):?><tr><td><b><?=e($v['title'])?></b><small class="subline"><?=e($v['youtube_video_id'])?></small></td><td><?=$v['is_published']?'Dərc edilib':'Gizli'?></td><td class="actions"><a href="?edit=<?=$v['id']?>">Redaktə</a><form method="post" onsubmit="return confirm('Video silinsin?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="link-danger">Sil</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="3">Video əlavə edilməyib.</td></tr><?php endif;?></tbody></table></div></section></div><?php admin_footer();?>